"""Profile the AnoMod client-side response logs: can they support windowed evaluation at all?

Before writing an adapter, check the shape of the data rather than assuming it:

  * how many cases there are, and what the anomaly labels look like from the folder names;
  * how many requests each case actually contains, and over what span;
  * what the status codes look like — the workload is generated by a fuzzer (EvoMaster), so a large
    share of 4xx may be *malformed requests* rather than failures of the system, and using them as the
    error signal would measure the fuzzer, not the service;
  * latency percentiles, so a sensible window size can be chosen.

Every conclusion drawn later depends on these numbers being what they are, so they are printed instead of
assumed.
"""
from __future__ import annotations

import json
import statistics
from collections import Counter
from datetime import datetime
from pathlib import Path
from typing import List

REPO_ROOT = Path(__file__).resolve().parents[2]
DATA = REPO_ROOT / "data" / "anomod" / "SN_data" / "api_responses"


def label_of(case: str) -> str:
    """Folder names encode the fault class: Normal_case, Code_*, DB_*, Perf_*, Service_* ..."""
    head = case.split("_2")[0] if "_2" in case else case
    for prefix in ("Code", "DB", "Perf", "Service", "Normal"):
        if case.startswith(prefix):
            return prefix
    return head.split("_")[0]


def load_case(path: Path) -> List[dict]:
    records = []
    with (path / "openapi_responses.jsonl").open(encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return records


def percentile(values: List[float], q: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(values)
    return ordered[min(len(ordered) - 1, int(q * (len(ordered) - 1)))]


def main() -> int:
    if not DATA.is_dir():
        print("api_responses not found under %s" % DATA)
        return 2
    cases = sorted(p for p in DATA.iterdir() if p.is_dir())
    print("cases: %d" % len(cases))
    print("")

    rows = []
    class_totals: Counter = Counter()
    per_case_span: List[float] = []
    for case in cases:
        records = load_case(case)
        if not records:
            continue
        stamps = []
        for record in records:
            try:
                stamps.append(datetime.fromisoformat(record["timestamp"]))
            except (KeyError, ValueError):
                continue
        span = (max(stamps) - min(stamps)).total_seconds() if stamps else 0.0
        per_case_span.append(span)
        codes = Counter()
        for record in records:
            code = int(record.get("status_code") or 0)
            bucket = "%dxx" % (code // 100) if code else "?"
            codes[bucket] += 1
            class_totals[bucket] += 1
        latencies = [float(r.get("latency_ms") or 0.0) for r in records]
        rows.append({
            "case": case.name,
            "label": label_of(case.name),
            "requests": len(records),
            "span_s": round(span, 1),
            "rps": round(len(records) / span, 2) if span else 0.0,
            "p50": round(statistics.median(latencies), 1),
            "p99": round(percentile(latencies, 0.99), 1),
            "codes": dict(codes),
        })

    print("%-52s %6s %7s %7s %8s %8s" % ("case", "reqs", "span_s", "rps", "p50ms", "p99ms"))
    print("-" * 96)
    for row in rows[:18]:
        print("%-52s %6d %7.0f %7.2f %8.1f %8.1f"
              % (row["case"][:52], row["requests"], row["span_s"], row["rps"], row["p50"], row["p99"]))
    if len(rows) > 18:
        print("... %d more cases" % (len(rows) - 18))

    print("")
    print("requests per case: min %d  median %d  max %d"
          % (min(r["requests"] for r in rows),
             int(statistics.median([r["requests"] for r in rows])),
             max(r["requests"] for r in rows)))
    print("case span (s):     min %.0f  median %.0f  max %.0f"
          % (min(per_case_span), statistics.median(per_case_span), max(per_case_span)))
    print("")
    print("status classes overall: %s" % dict(class_totals))
    total = sum(class_totals.values())
    if total:
        print("  4xx share %.1f%%   5xx share %.1f%%"
              % (100 * class_totals["4xx"] / total, 100 * class_totals["5xx"] / total))

    print("")
    print("labels present: %s" % dict(Counter(r["label"] for r in rows)))
    print("")
    print("5xx per case (the usable error signal):")
    for row in rows:
        if row["codes"].get("5xx"):
            print("  %-52s 5xx=%d  %s" % (row["case"][:52], row["codes"]["5xx"], row["codes"]))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
